  --muted: #6b7280;
  --accent: #2563eb;
  --accent-soft: #dbeafe;
  --danger: #dc2626;
  --success: #16a34a;
  --border: #e5e7eb;
  --focus: #2563eb;
  --radius: 12px;
  --shadow: 0 10px 30px rgba(15, 23, 42, 0.08);
