  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
}

.task-item.completed {
  background: var(--surface-2);
}

.task-item.completed .task-title {
  text-decoration: line-through;
  color: var(--muted);
}

.task-checkbox {
  width: 20px;
  height: 20px;
  accent-color: var(--success);
  cursor: pointer;
  flex-shrink: 0;
}

.task-checkbox:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.task-title {
  flex: 1;
  font-size: 15px;
  margin: 0;
  word-break: break-word;
}

.task-edit-input {
  flex: 1;
  font-size: 15px;
  padding: 8px 10px;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
}

.task-edit-input:focus {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.task-actions {
  display: flex;
  gap: 6px;
}

.icon-btn {
  border: 1px solid var(--border);
  background: var(--surface);
  border-radius: 8px;
  padding: 6px 10px;
  font-size: 13px;
  cursor: pointer;
  color: var(--muted);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.icon-btn:hover {
  background: var(--surface-2);
  color: var(--text);
}

.empty-state {
  text-align: center;
  padding: 40px 20px;
  color: var(--muted);
  border: 1px dashed var(--border);
  border-radius: 10px;
  background: var(--surface-2);
}

.empty-state h2 {
  margin: 0 0 8px;
  font-size: 18px;
  color: var(--text);
}

.empty-state p {
  margin: 0;
  font-size: 14px;
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 16px;
  color: var(--muted);
  font-size: 13px;
}

.clear-completed {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 13px;
  cursor: pointer;
  text-decoration: underline;
}

.clear-completed:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.clear-completed:hover {
  color: var(--text);
}

@media (max-width: 520px) {
  .app {
    padding: 20px 14px 48px;
  }

  .header {
    flex-direction: column;
    align-items: flex-start;
  }

  .add-form {
    flex-direction: column;
  }

  .task-item {
    flex-wrap: wrap;
  }

  .task-actions {
    width: 100%;
    justify-content: flex-end;
  }
}
