  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
}

.filter-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.filter-btn[aria-pressed="true"] {
  background: var(--accent);
