}

.clear-completed {
  background: none;
  border: none;
  color: var(--muted);
  font-size: 13px;
  cursor: pointer;
  text-decoration: underline;
}

.clear-completed:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.clear-completed:hover {
  color: var(--text);
}

@media (max-width: 520px) {
