workspace_write({"path":"app/page.js","content":""use client";

import { useEffect, useMemo, useRef, useState } from "react";

const STORAGE_KEY = "daylight.tasks.v1";

function loadTasks() {
  if (typeof window === "undefined") return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (t) => t && typeof t.id === "string" && typeof t.title === "string"
    );
  } catch {
    return [];
  }
}

function saveTasks(tasks) {
  if (typeof window === "undefined") return;
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks));
  } catch {
    // ignore storage errors
  }
}

function makeId() {
  return `t_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

export default function Home() {
  const [tasks, setTasks] = useState([]);
  const [filter, setFilter] = useState("all");
  const [newTitle, setNewTitle] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editValue, setEditValue] = useState("");
  const [hydrated, setHydrated] = useState(false);
  const editInputRef = useRef(null);

  useEffect(() => {
    setTasks(loadTasks());
    setHydrated(true);
  }, []);

  useEffect(() => {
    if (hydrated) saveTasks(tasks);
  }, [tasks, hydrated]);

  useEffect(() => {
    if (editingId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingId]);

  const visibleTasks = useMemo(() => {
    if (filter === "active") return tasks.filter((t) => !t.completed);
    if (filter === "completed") return tasks.filter((t) => t.completed);
    return tasks;
  }, [tasks, filter]);

  const activeCount = useMemo(() => tasks.filter((t) => !t.completed).length, [tasks]);
  const completedCount = useMemo(() => tasks.filter((t) => t.completed).length, [tasks]);

  function addTask(e) {
    e.preventDefault();
    const title = newTitle.trim();
    if (!title) return;
    const task = { id: makeId(), title, completed: false };
    setTasks((prev) => [task, ...prev]);
    setNewTitle("");
  }

  function toggleComplete(id) {
    setTasks((prev) =>
      prev.map((t) => (t.id === id ? { ...t, completed: !t.completed } : t))
    );
  }

  function deleteTask(id) {
    setTasks((prev) => prev.filter((t) => t.id !== id));
    if (editingId === id) {
      setEditingId(null);
      setEditValue("");
    }
  }

  function startEdit(task) {
    setEditingId(task.id);
    setEditValue(task.title);
  }

  function cancelEdit() {
    setEditingId(null);
    setEditValue("");
  }

  function commitEdit() {
    const title = editValue.trim();
    if (!title) {
      cancelEdit();
      return;
    }
    setTasks((prev) =>
      prev.map((t) => (t.id === editingId ? { ...t, title } : t))
    );
    setEditingId(null);
    setEditValue("");
  }

  function onEditKeyDown(e) {
    if (e.key === "Enter") {
      e.preventDefault();
      commitEdit();
    } else if (e.key === "Escape") {
      e.preventDefault();
      cancelEdit();
    }
  }

  function clearCompleted() {
    setTasks((prev) => prev.filter((t) => !t.completed));
  }

  return (
    <main className="app">
      <header className="header">
        <div>
          <h1 className="title">Daylight</h1>
          <p className="subtitle">A calm place to keep your tasks.</p>
        </div>
        <span className="count-badge" aria-live="polite">
          {activeCount} active · {completedCount} done
        </span>
      </header>

      <section className="card" aria-label="Task board">
        <form className="add-form" onSubmit={addTask}>
          <label htmlFor="new-task" className="sr-only" style={{ position: "absolute", left: "-9999px" }}>
            New task title
          </label>
          <input
            id="new-task"
            className="add-input"
            type="text"
            placeholder="What needs doing?"
            value={newTitle}
            onChange={(e) => setNewTitle(e.target.value)}
            aria-label="New task title"
          />
          <button type="submit" className="btn btn-primary" aria-label="Add task">
            Add
          </button>
        </form>

        <div className="filters" role="group" aria-label="Filter tasks">
          <button
            className="filter-btn"
            aria-pressed={filter === "all"}
            onClick={() => setFilter("all")}
          >
            All ({tasks.length})
          </button>
          <button
            className="filter-btn"
            aria-pressed={filter === "active"}
            onClick={() => setFilter("active")}
          >
            Active ({activeCount})
          </button>
          <button
            className="filter-btn"
            aria-pressed={filter === "completed"}
            onClick={() => setFilter("completed")}
          >
            Completed ({completedCount})
          </button>
        </div>

        {visibleTasks.length === 0 ? (
          <div className="empty-state" role="status">
            <h2>
              {filter === "all" && "No tasks yet"}
              {filter === "active" && "Nothing active"}
              {filter === "completed" && "Nothing completed"}
            </h2>
            <p>
              {filter === "all" && "Add your first task above to get started."}
              {filter === "active" && "All your tasks are done. Nice work."}
              {filter === "completed" && "Tasks you finish will appear here."}
            </p>
          </div>
        ) : (
          <ul className="task-list" aria-label="Tasks">
            {visibleTasks.map((task) => (
              <li
                key={task.id}
                className={`task-item ${task.completed ? "completed" : ""}`}
              >
                <input
                  type="checkbox"
                  className="task-checkbox"
                  checked={task.completed}
                  onChange={() => toggleComplete(task.id)}
                  aria-label={`Mark "${task.title}" as ${task.completed ? "active" : "completed"}`}
                />
                {editingId === task.id ? (
                  <input
                    ref={editInputRef}
                    className="task-edit-input"
                    type="text"
                    value={editValue}
                    onChange={(e) => setEditValue(e.target.value)}
                    onKeyDown={onEditKeyDown}
                    onBlur={commitEdit}
                    aria-label={`Edit title for "${task.title}"`}
                  />
                ) : (
                  <p className="task-title">{task.title}</p>
                )}
                <div className="task-actions">
                  <button
                    className="icon-btn"
                    onClick={() => startEdit(task)}
                    aria-label={`Edit "${task.title}"`}
                  >
                    Edit
                  </button>
                  <button
                    className="icon-btn"
                    onClick={() => deleteTask(task.id)}
                    aria-label={`Delete "${task.title}"`}
                  >
                    Delete
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}

        <div className="footer">
          <span>
            {tasks.length} {tasks.length === 1 ? "task" : "tasks"} total
          </span>
          {completedCount > 0 && (
            <button className="clear-completed" onClick={clearCompleted}>
              Clear completed
            </button>
          )}
        </div>
      </section>
    </main>
  );
}
